parser=argparse.ArgumentParser();parser.add_argument('--output-dir',type=Path);args=parser.parse_args()
repo=Path(__file__).resolve().parents[1];root=args.output_dir or repo;src=repo/'data-snapshots/rework';out=root/'question-banks';out.mkdir(parents=True,exist_ok=True)
def load(name):
 path=src/(name+'.json');return json.loads(path.read_text()if path.exists()else gzip.decompress((src/(name+'.json.gz')).read_bytes()).decode())
def norm(s):return re.sub('[^a-z0-9+#]','',unicodedata.normalize('NFKD',str(s)).encode('ascii','ignore').decode().lower())
def valid(s):
 return 1<=len(s)<=180 and len(norm(s))>=1 and bool(re.search('[A-Za-z0-9]',unicodedata.normalize('NFKD',s))) and not re.search(r'\b(?:porn|hentai|nigger|faggot|fuck|fucking|fucked|rape|raping|sex|sexual|incest|cum|cumming|slut|sluts|tits|boobs|pussy|nude|nudes)\b',s,re.I) and not re.match(r'^(?:Q\d+|\?+|unknown|unnamed|test game|Team Mate \d|Enemy \d)',s,re.I)
def ent(name,aliases=(),**kw):return {'name':str(name).strip(),'aliases':list(aliases),**kw}
def named(name):return [ent(x)if isinstance(x,str)else ent(x['name'],x.get('aliases',[]),**{k:v for k,v in x.items()if k not in ['name','aliases']})for x in load(name)]
# Existing snapshots are reused in broad unions. Historical banks are untouched.
def jsrows(file,prefix):return json.loads((repo/file).read_text().split(prefix,1)[1].split(';\n',1)[0])
legacy={meta['id']:[ent(a[0],a[2])for a in answers]for meta,answers in jsrows('expanded-banks.js','const rows=')}
pool=jsrows('question-answers.js','export const ANSWER_ROWS=')
for meta,ids in jsrows('question-catalog.js','const rows='):legacy[meta['id']]=[ent(pool[i][0],pool[i][2])for i in ids]
def union(ids):return [a for i in ids for a in legacy[i]]
def strings(data):return [ent(s)for s in data]
@functools.lru_cache(maxsize=600000)
def frequency(s):return zipf_frequency(s.lower(),'en')
packs=[];manifest=[]
def bank(id,family,topic,prompt,items,group=None,common=(),gems=(),aliases=None,noise=(),mixed=True,source='Recorded factual snapshots; see data-snapshots/rework/source-manifest.json and DATA-SOURCES.md.'):
 merged={}
 for a in items:
  if isinstance(a,str):a=ent(a)
  label=re.sub(r'\s+',' ',a['name']).strip();key=norm(label)
  if not valid(label):continue
  if key not in merged:merged[key]=ent(label,a.get('aliases',[]),prominence=a.get('prominence',0))
  else:merged[key]['aliases']+=a.get('aliases',[])+([label]if label!=merged[key]['name']else[])
 for label,other in (aliases or {}).items():
  if norm(label)in merged:
   parent=merged[norm(label)];parent['aliases']+=other
   for alias in other:
    key=norm(alias)
    if key!=norm(label)and key in merged:
     child=merged.pop(key);parent['aliases']+=[child['name']]+child['aliases']
 owners=collections.defaultdict(set)
 for k,a in merged.items():
  for alias in a['aliases']:
   if valid(alias):owners[norm(alias)].add(k)
 common={norm(s)for s in common};gems={norm(s)for s in gems};rows=[]
 for k,a in merged.items():
  f=frequency(a['name']);p=a.get('prominence',0)
  points=10 if k in common or f>=5 else 30 if f>=4.1 or p>=50 else 60 if f>=3.1 or p>=10 else 85
  if any(norm(x)in common for x in a['aliases']):points=10
  if k in gems or any(norm(x)in gems for x in a['aliases']):points=100
  alias=sorted({str(s).strip()for s in a['aliases']if valid(str(s).strip())and norm(s)!=k and norm(s)not in merged and len(owners[norm(s)])==1})
  rows.append([a['name'],points,alias])
 rows.sort(key=lambda a:a[0].casefold())
 if not rows:raise ValueError(id)
 if not any(a[1]==100 for a in rows):
  # A recognisable, unusual label rather than an unreadable minimum-frequency token.
  candidate=next((a for a in rows if a[1]>=60 and 5<=len(a[0])<=28),rows[-1]);candidate[1]=100
 payload=json.dumps(rows,ensure_ascii=False,separators=(',',':'));digest=hashlib.sha256(payload.encode()).hexdigest()[:16];filename=f'{id}.{digest}.json.gz';(out/filename).write_bytes(gzip.compress(payload.encode(),compresslevel=9,mtime=0))
 meta={'id':id,'family':family,'topic':topic,'prompt':prompt,'group':group or id,'answerCount':len(rows),'answerFile':filename,'dailyEligible':True,'funVersion':4,'mixed':mixed,'inputNoise':list(noise),'ranking':'familiarity-v3','source':source}
 packs.append(meta);manifest.append({**meta,'tiers':dict(collections.Counter(a[1]for a in rows)),'bytes':len(payload.encode()),'downloadBytes':(out/filename).stat().st_size,'sha256':hashlib.sha256(payload.encode()).hexdigest()});print(id,len(rows),flush=True)
 return rows
